<?php
require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$user=requireLogin($pdo);$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken($_POST);try{changePassword($pdo,(int)$user['user_id'],field('current_password'),field('new_password'),field('confirm_password'));startLogin($user);header('Location: profile.php',true,303);exit;}catch(Throwable $e){$error=$e;}}pageStart('Change Password');if($error)showError($error);echo '<form method="post">'.csrfField();formField('current_password','Current password','password');formField('new_password','New password','password');formField('confirm_password','Confirm new password','password');echo '<button class="btn btn-primary">Update Password</button></form>';pageEnd();
